insert into public.compounds (id, name, formula, recipe, catalyst, tier, points, riddle, locked_hint) values
  ('water', 'Water', 'H₂O', '{"H":2,"O":1}'::jsonb, null, 'basic', 5, 'You drink me, swim in me, and I''m 60% of you. Two of the lightest, one of the breath.', null),
  ('carbon-dioxide', 'Carbon Dioxide', 'CO₂', '{"C":1,"O":2}'::jsonb, null, 'basic', 5, 'I''m the fizz in your soda and the sigh you just exhaled. One of the pencil, two of the breath.', null),
  ('carbon-monoxide', 'Carbon Monoxide', 'CO', '{"C":1,"O":1}'::jsonb, null, 'basic', 5, 'Silent, invisible, and the reason your house has an alarm. I''m my fizzy sibling, but missing a breath.', null),
  ('methane', 'Methane', 'CH₄', '{"C":1,"H":4}'::jsonb, null, 'basic', 5, 'Cows make me, kitchens burn me. One dark atom surrounded by four tiny friends.', null),
  ('salt', 'Table Salt', 'NaCl', '{"Na":1,"Cl":1}'::jsonb, null, 'basic', 5, 'A metal that explodes in water + a poison gas = something you sprinkle on fries.', null),
  ('hydrochloric-acid', 'Hydrochloric Acid', 'HCl', '{"H":1,"Cl":1}'::jsonb, null, 'basic', 5, 'Your stomach is full of me right now. One light, one green and poisonous.', null),
  ('sodium-hydroxide', 'Sodium Hydroxide', 'NaOH', '{"Na":1,"O":1,"H":1}'::jsonb, null, 'basic', 5, 'Soap-makers and drain-unblockers love me. One each of three: salt''s metal, breath, and the lightest.', null),
  ('quicklime', 'Quicklime', 'CaO', '{"Ca":1,"O":1}'::jsonb, null, 'basic', 5, 'The bone-builder grabs a breath and becomes the stuff old builders used for mortar.', null),
  ('chalk', 'Chalk / Limestone', 'CaCO₃', '{"Ca":1,"C":1,"O":3}'::jsonb, null, 'basic', 5, 'Your teacher wrote with me, cliffs are built of me. Bones, pencil, and three breaths.', null),
  ('hydrogen-sulfide', 'Hydrogen Sulfide', 'H₂S', '{"H":2,"S":1}'::jsonb, null, 'basic', 5, 'I smell exactly like rotten eggs. I''m water''s evil twin — swap the breath for the yellow one.', null),
  ('sulfur-dioxide', 'Sulfur Dioxide', 'SO₂', '{"S":1,"O":2}'::jsonb, null, 'basic', 5, 'Volcanoes burp me, acid rain starts with me. The yellow one, holding two breaths.', null),
  ('nitrogen-dioxide', 'Nitrogen Dioxide', 'NO₂', '{"N":1,"O":2}'::jsonb, null, 'basic', 5, 'The brown haze over traffic jams. Air''s most common atom, holding two breaths.', null),
  ('laughing-gas', 'Laughing Gas', 'N₂O', '{"N":2,"O":1}'::jsonb, null, 'basic', 5, 'Dentists use me and you giggle. Two of the air''s main atom, one breath.', null),
  ('baking-soda', 'Baking Soda', 'NaHCO₃', '{"Na":1,"H":1,"C":1,"O":3}'::jsonb, null, 'basic', 5, 'Volcano science projects and fluffy cakes need me. Four different atoms, and breath appears three times.', null),
  ('calcium-chloride', 'Calcium Chloride', 'CaCl₂', '{"Ca":1,"Cl":2}'::jsonb, null, 'basic', 5, 'Thrown on icy roads and packed into moisture absorbers. The bone-builder meets two greens.', null),
  ('ammonia', 'Ammonia', 'NH₃', '{"N":1,"H":3}'::jsonb, 'pressure', 'catalyzed', 20, 'I feed half the world as fertilizer and I smell like cleaning day. Air''s atom with three tiny friends... but they won''t hold hands unless squeezed.', 'N ×1, H ×3 — needs 🗜️ Pressure.'),
  ('hydrogen-peroxide', 'Hydrogen Peroxide', 'H₂O₂', '{"H":2,"O":2}'::jsonb, 'electricity', 'catalyzed', 18, 'I''m water with one breath too many — I bleach hair and fizz on cuts. Getting that extra breath needs a jolt.', 'H ×2, O ×2 — needs ⚡ Electricity.'),
  ('ozone', 'Ozone', 'O₃', '{"O":3}'::jsonb, 'light', 'catalyzed', 18, 'I''m the sky''s sunscreen. Just breath, tripled — but only the sun''s rays can stitch me together.', 'O ×3 — needs ☀️ Light.'),
  ('glucose', 'Glucose', 'C₆H₁₂O₆', '{"C":6,"H":12,"O":6}'::jsonb, 'light', 'catalyzed', 25, 'Every leaf on campus is making me right now. Six, twelve, six — and the leaves'' secret ingredient.', 'C ×6, H ×12, O ×6 — needs ☀️ Light.'),
  ('sucrose', 'Table Sugar', 'C₁₂H₂₂O₁₁', '{"C":12,"H":22,"O":11}'::jsonb, 'light', 'catalyzed', 28, 'Your chai needs two spoons of me. Twelve pencils, twenty-two tinies, eleven breaths. Sugarcane grew me in the sun.', 'C ×12, H ×22, O ×11 — needs ☀️ Light.'),
  ('ethanol', 'Ethanol', 'C₂H₆O', '{"C":2,"H":6,"O":1}'::jsonb, 'enzyme', 'catalyzed', 22, 'Yeast makes me from sugar; hand sanitizer is mostly me. Two dark, six tiny, one breath — and something alive has to help.', 'C ×2, H ×6, O ×1 — needs 🧬 Enzyme.'),
  ('acetic-acid', 'Vinegar (Acetic Acid)', 'C₂H₄O₂', '{"C":2,"H":4,"O":2}'::jsonb, 'enzyme', 'catalyzed', 22, 'I''m the sour in your chips. Bacteria turn wine into me. Two, four, two.', 'C ×2, H ×4, O ×2 — needs 🧬 Enzyme.'),
  ('sulfuric-acid', 'Sulfuric Acid', 'H₂SO₄', '{"H":2,"S":1,"O":4}'::jsonb, 'heat', 'catalyzed', 22, 'The king of industrial chemicals; car batteries are full of me. Two tiny, one yellow, four breaths, forged in fire.', 'H ×2, S ×1, O ×4 — needs 🔥 Heat.'),
  ('nitric-acid', 'Nitric Acid', 'HNO₃', '{"H":1,"N":1,"O":3}'::jsonb, 'heat', 'catalyzed', 22, 'Rocket fuel and fertilizers start with me. One tiny, one from air, three breaths — burned into being.', 'H ×1, N ×1, O ×3 — needs 🔥 Heat.'),
  ('ethylene', 'Ethylene', 'C₂H₄', '{"C":2,"H":4}'::jsonb, 'heat', 'catalyzed', 18, 'I ripen bananas and I''m the start of every plastic bag. Crack oil with fire to find me: two and four.', 'C ×2, H ×4 — needs 🔥 Heat.'),
  ('bleach', 'Bleach', 'NaClO', '{"Na":1,"Cl":1,"O":1}'::jsonb, 'electricity', 'catalyzed', 18, 'Salt plus a breath, but only if you zap salty water. Your white shirts thank me.', 'Na ×1, Cl ×1, O ×1 — needs ⚡ Electricity.'),
  ('urea', 'Urea', 'CH₄N₂O', '{"C":1,"H":4,"N":2,"O":1}'::jsonb, 'pressure', 'catalyzed', 25, 'The first ''living'' chemical ever made in a lab — and yes, it''s in pee. Squeeze ammonia''s cousins with a pencil and a breath.', 'C ×1, H ×4, N ×2, O ×1 — needs 🗜️ Pressure.'),
  ('caffeine', 'Caffeine', 'C₈H₁₀N₄O₂', '{"C":8,"H":10,"N":4,"O":2}'::jsonb, 'enzyme', 'catalyzed', 35, 'Exam week runs on me. Coffee plants build me: eight, ten, four, two.', 'C ×8, H ×10, N ×4, O ×2 — needs 🧬 Enzyme.'),
  ('aspirin', 'Aspirin', 'C₉H₈O₄', '{"C":9,"H":8,"O":4}'::jsonb, 'acid', 'catalyzed', 35, 'Headache? Willow bark had my ancestor. Nine, eight, four — and a sour push.', 'C ×9, H ×8, O ×4 — needs 🧪 Acid.'),
  ('ester-banana', 'Banana Flavour (Isoamyl Acetate)', 'C₇H₁₄O₂', '{"C":7,"H":14,"O":2}'::jsonb, 'acid', 'catalyzed', 30, 'Fake banana candy tastes like me. Seven, fourteen, two — an acid has to bring us together.', 'C ×7, H ×14, O ×2 — needs 🧪 Acid.'),
  ('potassium-chloride', 'Potassium Chloride', 'KCl', '{"K":1,"Cl":1}'::jsonb, null, 'uncommon', 12, 'Low-sodium salt is secretly me. Banana''s metal meets the green gas.', null),
  ('saltpeter', 'Saltpeter', 'KNO₃', '{"K":1,"N":1,"O":3}'::jsonb, null, 'uncommon', 12, 'The ''boom'' part of fireworks. Banana metal, one from the air, three breaths.', null),
  ('rust', 'Rust', 'Fe₂O₃', '{"Fe":2,"O":3}'::jsonb, null, 'uncommon', 12, 'Every old bicycle on campus wears me. Two of the blood metal, three breaths.', null),
  ('copper-sulfate', 'Copper Sulfate', 'CuSO₄', '{"Cu":1,"S":1,"O":4}'::jsonb, null, 'uncommon', 12, 'Brilliant blue crystals from your school lab. The penny metal, the yellow one, four breaths.', null),
  ('sand', 'Sand / Quartz', 'SiO₂', '{"Si":1,"O":2}'::jsonb, null, 'uncommon', 12, 'Dubai has a LOT of me. The chip-maker''s element, holding two breaths.', null),
  ('phosphoric-acid', 'Phosphoric Acid', 'H₃PO₄', '{"H":3,"P":1,"O":4}'::jsonb, null, 'uncommon', 12, 'The tang in cola. Three tiny, one matchstick-head, four breaths.', null),
  ('sodium-fluoride', 'Sodium Fluoride', 'NaF', '{"Na":1,"F":1}'::jsonb, null, 'uncommon', 12, 'Your toothpaste''s secret weapon. Salt''s metal, but swap the green gas for the angriest element.', null),
  ('epsom-salt', 'Epsom Salt', 'MgSO₄', '{"Mg":1,"S":1,"O":4}'::jsonb, null, 'uncommon', 12, 'Sore muscles soak in me. The flash-bulb metal, the yellow one, four breaths.', null),
  ('magnesium-oxide', 'Magnesium Oxide', 'MgO', '{"Mg":1,"O":1}'::jsonb, 'heat', 'uncommon', 20, 'Light me and I burn blinding white, leaving white ash behind. Flash metal + one breath + fire.', 'Mg ×1, O ×1 — needs 🔥 Heat.'),
  ('alumina', 'Alumina (Sapphire)', 'Al₂O₃', '{"Al":2,"O":3}'::jsonb, 'heat', 'uncommon', 22, 'Add a pinch of impurity and I''m a sapphire. Two of the soda-can metal, three breaths, a furnace.', 'Al ×2, O ×3 — needs 🔥 Heat.'),
  ('pyrite', 'Fool''s Gold (Pyrite)', 'FeS₂', '{"Fe":1,"S":2}'::jsonb, 'heat', 'uncommon', 22, 'I look like treasure but I''m not. Blood metal with two yellows, cooked deep underground.', 'Fe ×1, S ×2 — needs 🔥 Heat.'),
  ('bone-mineral', 'Bone Mineral', 'Ca₃(PO₄)₂', '{"Ca":3,"P":2,"O":8}'::jsonb, 'enzyme', 'uncommon', 28, 'You''re holding your phone with me. Three bone-builders, two matchsticks, eight breaths — and your body''s machinery.', 'Ca ×3, P ×2, O ×8 — needs 🧬 Enzyme.'),
  ('teflon', 'Teflon (monomer)', 'C₂F₄', '{"C":2,"F":4}'::jsonb, 'pressure', 'uncommon', 30, 'Nothing sticks to me — not even eggs. Two pencils, four of the angriest element, squeezed hard.', 'C ×2, F ×4 — needs 🗜️ Pressure.'),
  ('lithium-carbonate', 'Lithium Carbonate', 'Li₂CO₃', '{"Li":2,"C":1,"O":3}'::jsonb, null, 'rare', 35, 'Every phone battery starts its life as me. Two of the lightest metal, a pencil, three breaths.', null),
  ('zinc-oxide', 'Zinc Oxide', 'ZnO', '{"Zn":1,"O":1}'::jsonb, null, 'rare', 30, 'The white stuff on lifeguards'' noses. The galvanizing metal, one breath.', null),
  ('silver-nitrate', 'Silver Nitrate', 'AgNO₃', '{"Ag":1,"N":1,"O":3}'::jsonb, null, 'rare', 35, 'Election ink that won''t wash off your finger. The mirror metal, one air, three breaths.', null),
  ('potassium-iodide', 'Potassium Iodide', 'KI', '{"K":1,"I":1}'::jsonb, null, 'rare', 30, 'Radiation-emergency pills. Banana metal meets the purple one.', null),
  ('silver-chloride', 'Silver Chloride', 'AgCl', '{"Ag":1,"Cl":1}'::jsonb, 'light', 'rare', 45, 'Old film photographs were made of me — I darken when the world looks at me. Mirror metal + green gas + a flash.', 'Ag ×1, Cl ×1 — needs ☀️ Light.'),
  ('silver-iodide', 'Silver Iodide', 'AgI', '{"Ag":1,"I":1}'::jsonb, 'pressure', 'rare', 50, 'The UAE sprays me into clouds to make it rain. Mirror metal + the purple one, packed tight.', 'Ag ×1, I ×1 — needs 🗜️ Pressure.'),
  ('gold-chloride', 'Gold Chloride', 'AuCl₃', '{"Au":1,"Cl":3}'::jsonb, 'acid', 'rare', 55, 'Gold doesn''t dissolve in anything... except the ''royal water''. One gold, three greens, and the strongest sour.', 'Au ×1, Cl ×3 — needs 🧪 Acid.'),
  ('lifepo4', 'Lithium Iron Phosphate', 'LiFePO₄', '{"Li":1,"Fe":1,"P":1,"O":4}'::jsonb, 'electricity', 'rare', 60, 'Electric cars run on me. Lightest metal, blood metal, matchstick, four breaths — charged up.', 'Li ×1, Fe ×1, P ×1, O ×4 — needs ⚡ Electricity.'),
  ('zinc-battery', 'Zinc Chloride', 'ZnCl₂', '{"Zn":1,"Cl":2}'::jsonb, 'electricity', 'rare', 45, 'Inside the cheap batteries in your TV remote. Galvanizing metal, two greens, a spark.', 'Zn ×1, Cl ×2 — needs ⚡ Electricity.'),
  ('heavy-water', 'Heavy Water', 'D₂O', '{"D":2,"O":1}'::jsonb, 'electricity', 'isotope', 90, 'I look exactly like water, but an ice cube of me sinks. Two heavy tinies, one breath, separated by a current.', 'D ×2, O ×1 — needs ⚡ Electricity.'),
  ('radiocarbon-co2', 'Radiocarbon CO₂', '¹⁴CO₂', '{"C14":1,"O":2}'::jsonb, null, 'isotope', 70, 'Archaeologists date mummies by me. The ticking pencil, holding two breaths.', null),
  ('heavy-oxygen-water', 'Heavy-Oxygen Water', 'H₂¹⁸O', '{"H":2,"O18":1}'::jsonb, null, 'isotope', 70, 'Hospitals use me to make PET-scan tracers. Ordinary tinies, one heavy breath.', null),
  ('uranium-hexafluoride', 'Uranium Hexafluoride', 'UF₆', '{"U235":1,"F":6}'::jsonb, 'heat', 'isotope', 120, 'The most dangerous thing in this game. One fissile heavyweight, six of the angriest element, white-hot.', 'U-235 ×1, F ×6 — needs 🔥 Heat.'),
  ('chlorophyll', 'Chlorophyll a', 'C₅₅H₇₂MgN₄O₅', '{"C":55,"H":72,"Mg":1,"N":4,"O":5}'::jsonb, 'light', 'legendary', 100, 'Every green thing on Earth wears me. A huge ring with a flash-metal heart — fifty-five, seventy-two, one, four, five. Sunlight only.', 'C ×55, H ×72, Mg ×1, N ×4, O ×5 — needs ☀️ Light.'),
  ('heme', 'Heme', 'C₃₄H₃₂FeN₄O₄', '{"C":34,"H":32,"Fe":1,"N":4,"O":4}'::jsonb, 'enzyme', 'legendary', 100, 'I''m why your blood is red. Chlorophyll''s cousin, but my heart is the blood metal. Thirty-four, thirty-two, one, four, four.', 'C ×34, H ×32, Fe ×1, N ×4, O ×4 — needs 🧬 Enzyme.')
